import{z as s,x as A,o as E,c as n,q as i,j as o,D as e,d as l,s as B,S as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"kABI 与模块签名","description":"","frontmatter":{"title":"kABI 与模块签名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kabi-module-signing.md","filePath":"cs/kabi-module-signing.md","lastUpdated":1791063341000}'),d={name:"cs/kabi-module-signing.md"};function c(p,a,C,_,D,m){const r=A("Mermaid");return E(),n("div",null,[a[2]||(a[2]=i('<h1 id="kabi-与模块签名" tabindex="-1">kABI 与模块签名 <a class="header-anchor" href="#kabi-与模块签名" aria-label="Permalink to &quot;kABI 与模块签名&quot;">​</a></h1><div class="epigraph"><p>发行版冻结一组内核符号的 ABI，使闭源或 DKMS 模块可在更新间加载；模块签名让 [Secure Boot](/cs/secure-boot) 下只有可信模块能进核。</p><footer>—— 据 Linux 模块签名文档；发行版 kABI 白皮书直觉；[livepatch](/cs/livepatch) 为替换对照</footer></div><p><a href="/cs/kernel-config-build">配置</a> 产出模块。缺口是 <strong>能不能加载</strong>：符号 CRC、签名、与 GPL-only 符号。观测/安全启动课序在此收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>modprobe</code> 解析未定义符号。kABI：发行版保证部分符号稳定。缺口：自己编的内核无此保证；签名：<code>CONFIG_MODULE_SIG</code>，密钥在 MOK。本课不把如何绕过签名当内容。</p><p><span class="marginnote"> vermagic 匹配配置。对象是加载策略，不是 C 调用约定课。</span></p><p><span class="marginnote">术语翻译：vermagic 是模块头部的一串「出厂配方」——编译它的内核版本、编译器、关键配置项。加载时内核逐项比对，配方对不上就拒绝，防止拿给 5.15 编的模块硬塞进 6.8 的内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载：验签名 → 验 vermagic → 重定位。对照 <a href="/cs/linux-capabilities">capabilities</a>：<code>CAP_SYS_MODULE</code>。对照 livepatch：也是模块。对照 <a href="/cs/chardev-ioctl">ioctl</a>：模块常注册 cdev。</p>',9)),(E(),o(t,null,{default:e(()=>[B(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20KO%5B%22.ko%22%5D%20--%3E%20SIG%5B%22%E9%AA%8C%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIG%20--%3E%20VER%5B%22vermagic%2FkABI%22%5D%0A%20%20VER%20--%3E%20REL%5B%22%E9%93%BE%E6%8E%A5%E8%BF%9B%E5%86%85%E6%A0%B8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>kABI+签名把「内核可扩展」限制在可信与兼容的模块上，服务稳定性和安全启动。自编译内核则你就是 ABI。不要写成驱动商店。与 <a href="/cs/ebpf-observability">eBPF</a>：BPF 不走模块符号表同一套。</p><p>崩溃的模块 taint 内核，影响支持。</p><p>实现上：CRC 对符号类型变了就会拒载。Secure Boot 下未签名模块直接失败。GPL-only 符号限制专有模块能钩的深度。 读法上只引用<a href="/cs/kernel-config-build">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">直觉类比：符号 CRC 像插头与插座的孔位——内核结构体一改，孔位就变，带着旧「插头」的模块插不上。kABI 冻结就是发行版承诺：清单里的插座永不改孔位。</span></p>',5)),(E(),o(t,null,{default:e(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%91%E8%A1%8C%E7%89%88%E6%9B%B4%E6%96%B0%EF%BC%9A%E5%8A%A8%E4%BA%86%E6%9F%90%E4%B8%AA%E7%BB%93%E6%9E%84%E4%BD%93%E5%B8%83%E5%B1%80%22%5D%20--%3E%20B%5B%22%E9%87%8D%E6%96%B0%E8%AE%A1%E7%AE%97%E5%8F%97%E5%BD%B1%E5%93%8D%E7%AC%A6%E5%8F%B7%E7%9A%84%20CRC%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%AC%AC%E4%B8%89%E6%96%B9%E6%A8%A1%E5%9D%97%E5%B8%A6%E7%9D%80%E6%97%A7%20CRC%20%E6%9D%A5%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20C%20--%3E%20D%5B%22CRC%20%E4%B8%80%E8%87%B4%EF%BC%9A%E6%AD%A3%E5%B8%B8%E9%93%BE%E6%8E%A5%E8%BF%9B%E5%86%85%E6%A0%B8%22%5D%0A%20%20C%20--%3E%20E%5B%22CRC%20%E4%B8%8D%E4%B8%80%E8%87%B4%EF%BC%9A%E6%8B%92%E8%BD%BD%EF%BC%8C%E6%8A%A5%E7%89%88%E6%9C%AC%E4%B8%8D%E5%8C%B9%E9%85%8D%22%5D%0A%20%20A%20--%3E%20F%5B%22%E8%8B%A5%E7%AC%A6%E5%8F%B7%E5%9C%A8%20kABI%20%E5%86%BB%E7%BB%93%E6%B8%85%E5%8D%95%E9%87%8C%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%8F%91%E8%A1%8C%E7%89%88%E8%AE%BE%E6%B3%95%E4%BF%9D%E6%8C%81%20CRC%20%E4%B8%8D%E5%8F%98%EF%BC%8C%E6%A8%A1%E5%9D%97%E7%85%A7%E5%B8%B8%E5%8F%AF%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>kABI 与模块签名</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 GPL 符号争议。不保证 Android GKI 的细节。下一单元虚拟化：hypervisor 类型。</p><p>版本字段会变，课序钉的是机制对象「kABI 与模块签名」，不是某一主线内核的结构体名。 后课默认：模块要匹配 ABI 且可验签。第一类/第二类 hypervisor，下一课。</p><p><span class="marginnote">常见误区：初学者容易以为「模块加载失败是代码有 bug」。实际上多数拒载发生在链接之前——签名、vermagic、符号 CRC 三道检查任一不过，模块的代码一行都还没执行就出门被拦。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模块加载检查符号、vermagic、可选签名。</li><li>发行版 kABI 冻结子集以便外模块。</li><li>虚拟化类型是下一单元。</li><li>出处：module signing；kbuild；发行版 kABI。</li></ul>',8))])}const k=s(d,[["render",c]]);export{u as __pageData,k as default};
